script:
frappe.ui.form.on("Project", {
    validate: function(frm) {
        var duplicateFound = false;
        var participants = {};

        frm.doc.custom_ts_details.forEach(function(row) {
            var key = row.pt_role + "_" + row.pt_participant;
            if (participants[key]) {
                var existingRow = participants[key];
                // Проверяем пересечение периодов действия
                if ((row.pt_valid_from && row.pt_valid_for) &&
                    (existingRow.pt_valid_from && existingRow.pt_valid_for) &&
                    ((row.pt_valid_from >= existingRow.pt_valid_from && row.pt_valid_from <= existingRow.pt_valid_for) ||
                    (row.pt_valid_for >= existingRow.pt_valid_from && row.pt_valid_for <= existingRow.pt_valid_for))) {
                    duplicateFound = true;
                    return false; // break the loop
                } else if (!row.pt_valid_from || !row.pt_valid_for) {
                    frappe.msgprint(__("Внимание! В проектной команде обнаружен дублирующий участник или группа. Если это не ошибка, укажите для дублей разные периоды действия"));
                    frappe.validated = false;
                }
            }
            participants[key] = {
                pt_valid_from: row.pt_valid_from,
                pt_valid_for: row.pt_valid_for
            };
        });

        if (duplicateFound) {
            frappe.msgprint(__("Внимание! В вашей проектной команде уже есть участник или группа с этой ролью и периодом действия"));
            frappe.validated = false;
        }
    }
});
